"""Compiler-owned source declarations shared by the structural scanners."""


def compiler_generated(text):
    # A generated filename alone does not exempt authored embedded policy or
    # bundled code. These headers identify reproducible protocol compiler output.
    header = text[:512]
    return ("Generated by the protocol buffer compiler." in header and "DO NOT EDIT" in header
            or "automatically generated by the FlatBuffers compiler" in header and "do not modify" in header.lower())
